@startuml

class Customer {
  + VATnumber : string
  + Name : string
  + PhoneNumber : string
  + Address : string
}

class DeliveryCenter {
  + Name : string
  + Address : string
}

class Package {
  + IdentifierCode : string
  + Weight : float
  + Type : string
}

class Courier {
  + VATnumber : string
  + Name : string
  + PhoneNumber : string
}

Customer "1" -- "1" DeliveryCenter : associated with
Customer "1" -- "0..*" Package : sends
Customer "1" -- "0..*" Package : receives
DeliveryCenter "1" -- "0..*" Courier : employs
DeliveryCenter "1" -- "0..*" Package : processes
Courier "1" -- "0..*" Package : delivers

@enduml

